import numpy as np

# Check L1: k^(4/3) * (121)^(1/3) <= 22
def check_L1(k):
    return (k**(4/3)) * (121**(1/3))

# Check L2: 22 < (k+1) * (121*k)^(1/3)
def check_L2(k):
    return 22 < (k + 1) * ((121 * k)**(1/3))

print("--- Checking L1 ---")
for k in range(1, 5):
    L1_val = check_L1(k)
    print(f"k={k}: L1 value = {L1_val:.3f}. Condition L1 met: {L1_val <= 22}")

print("\n--- Checking L2 ---")
for k in range(1, 5):
    L2_val = check_L2(k)
    print(f"k={k}: L2 condition met: {L2_val}")
